/** A logo too dark to see on a dark board, like Apple's black: drawn in the text color instead. */
export function inkLogo(hex: string): boolean {
  const n = parseInt(hex, 16);
  return ((n >> 16) & 255) * 0.299 + ((n >> 8) & 255) * 0.587 + (n & 255) * 0.114 < 60;
}
